Status shape(const FieldOrder& order,std::initializer_list<StableId> names){if(order.empty())return common_success();std::set<StableId> keys(names);if(keys.size()!=order.size())return common_failure("InvalidNavalRepairFieldOrder");for(const auto& key:order)if(keys.erase(key)!=1)return common_failure("InvalidNavalRepairFieldOrder",key);return common_success();}
