void dec(const V& v,NavalRepairTerms& r,const StableId& p){boundary::fields(v,{"actor_id","fleet_id","army_id","vessel_id","unit_id","captain_actor_id","formation_source_id","command_source_id","rule_id","inventory_id","owner","anchor","duration","integrity_before","integrity_after","crew_ids","participants","materials"},{},p);r.field_order=boundary::order(v);dec(boundary::field(v,"actor_id",p),r.actor_id,checkpoint_decode_boundary_join({p,"/actor_id"}));dec(boundary::field(v,"fleet_id",p),r.fleet_id,checkpoint_decode_boundary_join({p,"/fleet_id"}));dec(boundary::field(v,"army_id",p),r.army_id,checkpoint_decode_boundary_join({p,"/army_id"}));dec(boundary::field(v,"vessel_id",p),r.vessel_id,checkpoint_decode_boundary_join({p,"/vessel_id"}));dec(boundary::field(v,"unit_id",p),r.unit_id,checkpoint_decode_boundary_join({p,"/unit_id"}));dec(boundary::field(v,"captain_actor_id",p),r.captain_actor_id,checkpoint_decode_boundary_join({p,"/captain_actor_id"}));dec(boundary::field(v,"formation_source_id",p),r.formation_source_id,checkpoint_decode_boundary_join({p,"/formation_source_id"}));dec(boundary::field(v,"command_source_id",p),r.command_source_id,checkpoint_decode_boundary_join({p,"/command_source_id"}));dec(boundary::field(v,"rule_id",p),r.rule_id,checkpoint_decode_boundary_join({p,"/rule_id"}));dec(boundary::field(v,"inventory_id",p),r.inventory_id,checkpoint_decode_boundary_join({p,"/inventory_id"}));dec(boundary::field(v,"owner",p),r.owner,checkpoint_decode_boundary_join({p,"/owner"}));dec(boundary::field(v,"anchor",p),r.anchor,checkpoint_decode_boundary_join({p,"/anchor"}));dec(boundary::field(v,"duration",p),r.duration,checkpoint_decode_boundary_join({p,"/duration"}));dec(boundary::field(v,"integrity_before",p),r.integrity_before,checkpoint_decode_boundary_join({p,"/integrity_before"}));dec(boundary::field(v,"integrity_after",p),r.integrity_after,checkpoint_decode_boundary_join({p,"/integrity_after"}));dec(boundary::field(v,"crew_ids",p),r.crew_ids,checkpoint_decode_boundary_join({p,"/crew_ids"}));dec(boundary::field(v,"participants",p),r.participants,checkpoint_decode_boundary_join({p,"/participants"}));dec(boundary::field(v,"materials",p),r.materials,checkpoint_decode_boundary_join({p,"/materials"}));}
Status walk(CodecVisitor& c,NavalRepairTerms& r){c.object("actor_id",[&](auto& v){return walk(v,r.actor_id);});c.object("fleet_id",[&](auto& v){return walk(v,r.fleet_id);});c.object("army_id",[&](auto& v){return walk(v,r.army_id);});c.object("vessel_id",[&](auto& v){return walk(v,r.vessel_id);});c.object("unit_id",[&](auto& v){return walk(v,r.unit_id);});c.object("captain_actor_id",[&](auto& v){return walk(v,r.captain_actor_id);});c.object("formation_source_id",[&](auto& v){return walk(v,r.formation_source_id);});c.object("command_source_id",[&](auto& v){return walk(v,r.command_source_id);});c.object("rule_id",[&](auto& v){return walk(v,r.rule_id);});c.object("inventory_id",[&](auto& v){return walk(v,r.inventory_id);});c.object("owner",[&](auto& v){return walk(v,r.owner);});c.object("anchor",[&](auto& v){return walk(v,r.anchor);});c.object("duration",[&](auto& v){return walk(v,r.duration);});c.object("integrity_before",[&](auto& v){return walk(v,r.integrity_before);});c.object("integrity_after",[&](auto& v){return walk(v,r.integrity_after);});c.object("crew_ids",[&](auto& v){return walk(v,r.crew_ids);});c.object("participants",[&](auto& v){return walk(v,r.participants);});c.object("materials",[&](auto& v){return walk(v,r.materials);});walk(c,r.field_order);if(!c.status().ok)return c.status();auto check=shape(r.field_order,{"actor_id","fleet_id","army_id","vessel_id","unit_id","captain_actor_id","formation_source_id","command_source_id","rule_id","inventory_id","owner","anchor","duration","integrity_before","integrity_after","crew_ids","participants","materials"});return check.ok?c.status():c.reject(check.error.original.code);}
