void dec(const V& v,NavalRepairResult& r,const StableId& p){boundary::fields(v,{"id","action_id","actor_id","request_key","reason","interruption_source_id","tick","success"},{},p);r.field_order=boundary::order(v);dec(boundary::field(v,"id",p),r.id,checkpoint_decode_boundary_join({p,"/id"}));dec(boundary::field(v,"action_id",p),r.action_id,checkpoint_decode_boundary_join({p,"/action_id"}));dec(boundary::field(v,"actor_id",p),r.actor_id,checkpoint_decode_boundary_join({p,"/actor_id"}));dec(boundary::field(v,"request_key",p),r.request_key,checkpoint_decode_boundary_join({p,"/request_key"}));dec(boundary::field(v,"reason",p),r.reason,checkpoint_decode_boundary_join({p,"/reason"}));dec(boundary::field(v,"interruption_source_id",p),r.interruption_source_id,checkpoint_decode_boundary_join({p,"/interruption_source_id"}));dec(boundary::field(v,"tick",p),r.tick,checkpoint_decode_boundary_join({p,"/tick"}));dec(boundary::field(v,"success",p),r.success,checkpoint_decode_boundary_join({p,"/success"}));}
